    $stmt->bind_param("ssisssi", $full_content, $excerpt, $read_time, $image_url, $author, $category, $id);
    $stmt->execute();
    echo "SUCCESS: Updated Eidgah story (ID: $id) with 5 distinct notebook pages!\n";
} else {
    $stmt = $conn->prepare("INSERT INTO stories (title, author_name, category, excerpt, content, read_time, image_url, views, likes) VALUES (?, ?, ?, ?, ?, ?, ?, 120, 48)");
    $stmt->bind_param("sssssis", $story_title, $author, $category, $excerpt, $full_content, $read_time, $image_url);
    $stmt->execute();
    echo "SUCCESS: Inserted Eidgah story with 5 distinct notebook pages!\n";
}
